 function invoke(harness,command,args,context){if(!['grade','summary'].includes(command))throw new Error('Only grade and summary executable');const seq=String(++sequence).padStart(3,'0'),argv=[harness,command,...args],out=path.join(directory,'logs',seq+'-'+command);fs.mkdirSync(path.dirname(out),{recursive:true});const startedAt=new Date().toISOString(),before=sha(fs.readFileSync(context.batch));const result=spawnSync(process.execPath,argv,{encoding:'utf8',shell:false,windowsHide:true,maxBuffer:16*1024*1024});fs.writeFileSync(out+'.stdout.txt',result.stdout??'',{flag:'wx'});fs.writeFileSync(out+'.stderr.txt',result.stderr??'',{flag:'wx'});const after=sha(fs.readFileSync(context.batch));const row={sequence,startedAt,completedAt:new Date().toISOString(),command,argv,harnessSha256:sha(fs.readFileSync(harness)),...context,batchBeforeSha256:before,batchAfterSha256:after,exitCode:result.status,signal:result.signal??null,error:result.error?.message??null,stdoutFile:out+'.stdout.txt',stderrFile:out+'.stderr.txt'};fs.appendFileSync(log,JSON.stringify(row)+'\n');return row;}
 for(const r of inv.reviews){if(r.action!=='EXACT_MATCH_ELIGIBLE')continue;const match=r.matches[0],batch=json(match.batch),caseState=batch.cases[r.variant],attempt=caseState.attempts.find(a=>a.attemptId===r.attemptId),originalReview=json(r.file);
